-- Ajuste organização, e-mails e matérias antes de executar manualmente.
-- class_id = null significa todas as turmas da matéria.
begin;
create temp table teacher_subject_seed(email text primary key,subject_name text not null) on commit drop;
insert into teacher_subject_seed values ('prof.fisica@example.com','Física'),('prof.redacao@example.com','Redação'),('prof.linguagens@example.com','Linguagens'),('prof.biologia@example.com','Biologia'),('prof.quimica@example.com','Química'),('prof.humanas@example.com','Humanas');
do $$ declare v_org uuid;v_count int;v_row record;v_uid uuid;v_membership uuid;v_subject uuid;begin select count(*) into v_count from app.organizations where lower(trim(name))=lower('Nexo Avalia');if v_count<>1 then raise exception 'Esperada uma organização Nexo Avalia; encontradas %.',v_count;end if;select id into v_org from app.organizations where lower(trim(name))=lower('Nexo Avalia') limit 1;for v_row in select * from teacher_subject_seed loop select id into v_uid from auth.users where lower(email)=lower(v_row.email) limit 1;if v_uid is null then raise exception 'Usuário não encontrado: %',v_row.email;end if;select id into v_membership from app.memberships where organization_id=v_org and auth_uid=v_uid limit 1;if v_membership is null then raise exception 'Membership não encontrada: %',v_row.email;end if;select id into v_subject from app.subjects where organization_id=v_org and lower(public.unaccent(name))=lower(public.unaccent(v_row.subject_name)) limit 1;if v_subject is null then raise exception 'Matéria não encontrada: %',v_row.subject_name;end if;update app.memberships set role='teacher'::app.user_role,status='active' where id=v_membership;delete from app.teacher_assignments where membership_id=v_membership;insert into app.teacher_assignments(organization_id,membership_id,subject_id,class_id) values(v_org,v_membership,v_subject,null::uuid);end loop;end $$;
commit;
